after(async () => { await harness?.stop(); for (const name of ['FINITUDE_ADMIN_IMPORTS_ENABLED', 'FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY', 'ADMIN_IMPORT_S3_BUCKET_NAME', 'S3_BUCKET_NAME']) delete process.env[name]; });

/**
 * An import of one uploaded file per item of `tracks`, reviewed as "Amet Collection" crediting `album` (Lorem Ensemble by default),
 * each track holding the given entries (null: none) as an applied lookup candidate leaves them: automatic, written into the draft.
 */
async function project(storage: Storage, tracks: (ImportArtistEntry[] | null)[], album: ImportArtistEntry[] = [entry('Lorem Ensemble')], title = 'Amet Collection'): Promise<{ item: AdminImportDetailV2; slots: string[] }> {
    const slots = tracks.map(() => randomUUID()), names = slots.map((_slot, index) => `0${index + 1} - Synthetic.wav`);
    const created = await createAdminImport(by, { operationId: randomUUID(), manifest: { rootLabel: 'Synthetic Amet', files: slots.map((slotId, index) => ({ slotId, filename: names[index], relativePath: names[index], byteLength: wav().length })) } });
    let item = created.item;
    for (const [index, slotId] of slots.entries()) item = (await uploadAdminImportAsset(by, item.id, slotId, mutation(item.revision), file(names[index]), storage)).item;
    const draft: ImportDraftV2 = { album: { title, artists: album, label: null, releaseDate: { year: 2026, month: 3, day: 14 }, visibility: 'public' },
        tracks: slots.map((slotId, index) => ({ slotId, title: `Song ${index + 1}`, discNumber: 1, trackNumber: index + 1, ...(tracks[index] ? { artists: tracks[index]! } : {}) })) };
    const origins = Object.fromEntries(slots.filter((_slot, index) => tracks[index]).map(slotId => [`tracks:${slotId}:artists`, 'automatic']));
    await imports().updateOne({ _id: new ObjectId(item.id) }, { $set: { draft, draftOrigins: origins } });
    return { item: (await getAdminImport(by, item.id)).item, slots };
}
/** Approves the shown project with the given track selections (every listed track selected by default) and runs the worker. */
async function publish(storage: Storage, item: AdminImportDetailV2, options: ApprovalOptions = {}) {
    await publishAdminImport(by, item.id, approvalBody(item, options));
    const frozen = (await stored(item.id)).media!.publication!;
    await runAdminImportPublicationOnce(storage, item.id);
    return { frozen, done: (await getAdminImport(by, item.id)).item };
}
const credits = async (trackId: string) => (await row('audioTracks', trackId))!.credits as { subjectId: string; role: string; joinPhrase?: string; order: number; creditId: string }[];

test('a single-artist Album whose tracks agree publishes format 3 with Track Credits exactly the Album\'s primaries, and no other Artist', async () => {
    const storage = new Storage(), { item, slots } = await project(storage, [[entry('lorem ensemble')], [entry('Lorem Ensemble', 'primary', ' & ')]]);
    // Agreeing tracks are not listed: the summary sends no track keys, and the approval needs no selection.
    const summary = (await getAdminImportLookup(by, item.id)).summary;
    assert.deepEqual(['trackArtists', 'trackIdentities'].filter(name => name in summary), []);
    const { frozen, done } = await publish(storage, item);
    assert.deepEqual([frozen.schemaVersion, 'trackArtists' in frozen, 'trackIdentities' in frozen, done.publication], [3, false, false, 'complete']);
    const album = await row('albums', done.published!.albumId), [lorem] = done.published!.artistIds;
    const expected = [{ creditId: `import_primary_${lorem}`, subjectType: 'artist', subjectId: lorem, role: 'primary', order: 0 }];
    assert.deepEqual(album!.credits, expected);
    for (const trackId of done.published!.trackIds) assert.equal(JSON.stringify(await credits(trackId)), JSON.stringify(expected));
    assert.deepEqual([await counts(), slots.length], [{ artists: 1, albums: 1, audioTracks: 2 }, 2]);
    // The track entries stay automatic after the approval; every other value is the administrator's own.
    const origins = (await stored(item.id)).draftOrigins!;
    assert.deepEqual([origins[`tracks:${slots[0]}:artists`], origins['album:title']], ['automatic', 'administrator']);
});

test('a featured-artist track publishes format 4 with its own Credits and a new track-only Artist, while the other track keeps the Album\'s primaries', async () => {
    const storage = new Storage(), { item, slots } = await project(storage, [null, [lead(), guest()]]);
    const summary = (await getAdminImportLookup(by, item.id)).summary, guestKey = handle(`id:${mbid(3)}`);
    assert.deepEqual(summary.trackArtists!.map(track => [track.slotId, track.entries.map(value => value.identity)]), [[slots[1], [item.draft.album.artists[0].key, guestKey]]]);
    assert.deepEqual(summary.trackIdentities, [{ key: guestKey, name: 'Ipsum Guest', musicBrainzId: mbid(3), slotIds: [slots[1]] }]);
    // The guest has no candidate, so its new Artist is preselected and records its MusicBrainz ID.
    const writes = [{ scope: 'artist', entryKey: guestKey, musicBrainzId: mbid(3), replaces: null }];
    const { frozen, done } = await publish(storage, item, { trackArtists: [{ slotId: slots[1], selected: true }], musicBrainzIds: writes });
    assert.equal(frozen.schemaVersion, 4);
    const [lorem, ipsum] = done.published!.artistIds;
    assert.deepEqual(frozen.trackIdentities!.map(value => [value.entryKey, value.name, value.musicBrainzId, value.artistId, value.newArtist]), [[guestKey, 'Ipsum Guest', mbid(3), ipsum, true]]);
    assert.deepEqual(frozen.trackArtists, [{ slotId: slots[1], entries: [{ name: 'Lorem Ensemble', role: 'primary', joinPhrase: ' feat. ', artistId: lorem }, { name: 'Ipsum Guest', role: 'featured', joinPhrase: null, artistId: ipsum }] }]);
    assert.deepEqual([frozen.artists!.length, frozen.artistId], [1, lorem]);
    const [first, second] = done.published!.trackIds.map(id => id);
    assert.deepEqual(await credits(second), [{ creditId: `import_primary_${lorem}`, subjectType: 'artist', subjectId: lorem, role: 'primary', order: 0, joinPhrase: ' feat. ' },
        { creditId: `import_featured_${ipsum}`, subjectType: 'artist', subjectId: ipsum, role: 'featured', order: 1 }]);
    assert.deepEqual(await credits(first), [{ creditId: `import_primary_${lorem}`, subjectType: 'artist', subjectId: lorem, role: 'primary', order: 0 }]);
    assert.deepEqual((await row('audioTracks', second))!.artistIds, [lorem, ipsum]);
    // The track-only Artist takes the draft's visibility and its ID, never the Album in albumIds, and is not credited on the Album.
    const created = await row('artists', ipsum), album = await row('albums', done.published!.albumId);
    assert.deepEqual([created!.name, created!.visibility, created!.albumIds, created!.musicBrainzId], ['Ipsum Guest', 'public', [], mbid(3)]);
    assert.deepEqual(album!.credits.map((credit: { subjectId: string }) => credit.subjectId), [lorem]);
});

test('a track-only Artist is reused by its exact ID, created without candidates, and needs an explicit choice for a name candidate', async () => {
    const storage = new Storage(), holder = new ObjectId(), named = new ObjectId();
    await db().collection('artists').insertMany([{ _id: holder, name: 'Holder Spelling', musicBrainzId: mbid(3), albumIds: [], visibility: 'public', lifecycleStatus: 'ready' },
        { _id: named, name: 'Dolor Guest', albumIds: [], visibility: 'hidden', lifecycleStatus: 'ready' }]);
    const { item, slots } = await project(storage, [[lead(), guest()], [lead(), guest('Dolor Guest', null)], [lead(), guest('Sit Guest', null)]]);
    const selected = slots.map(slotId => ({ slotId, selected: true })), before = await stored(item.id);
    // The name candidate is neither answered nor preselected: nothing is written.
    await assert.rejects(publishAdminImport(by, item.id, approvalBody(item, { trackArtists: selected })), code('ADMIN_IMPORT_REVIEW_REQUIRED'));
    assert.deepEqual(await stored(item.id), before);
    // Review answers it with a decision on the track-only identity's handle, bound to its name.
    const candidate = (await adminImportDuplicateCandidates(by, item.id)).items.find(value => value.id === named.toHexString())!;
    const decisions = [...item.decisions, { scope: 'artist', slotId: null, entryKey: handle('name:dolor guest'), boundName: 'Dolor Guest', action: 'reuse', candidateId: candidate.id, candidateRevision: candidate.revision }];
    const decided = (await decideAdminImportDuplicates(by, item.id, { ...mutation(item.revision), decisions })).item;
    assert.ok(decided.decisions.some(value => value.entryKey === handle('name:dolor guest')));
    const { frozen, done } = await publish(storage, decided, { trackArtists: selected });
    assert.deepEqual(frozen.trackIdentities!.map(value => [value.name, value.artistId === holder.toHexString(), value.artistId === named.toHexString(), value.newArtist]),
        [['Ipsum Guest', true, false, false], ['Dolor Guest', false, true, false], ['Sit Guest', false, false, true]]);
    // A reused track-only Artist keeps its name, visibility and ID, and never gains the Album.
    assert.deepEqual([(await row('artists', holder.toHexString()))!.name, (await row('artists', named.toHexString()))!.albumIds, (await row('artists', named.toHexString()))!.visibility], ['Holder Spelling', [], 'hidden']);
    const [, , third] = done.published!.trackIds;
    assert.equal((await credits(third))[1].subjectId, frozen.trackIdentities![2].artistId);
    assert.deepEqual(await counts(), { artists: 4, albums: 1, audioTracks: 3 });
});

test('a track entry crediting the same artist as an Album entry shares its decision and Artist; deselecting tracks publishes them with the Album\'s primaries', async () => {
    const storage = new Storage(), album = [entry('Lorem Ensemble', 'primary', ' feat. '), entry('Album Guest', 'featured', null, mbid(3))];
    const { item, slots } = await project(storage, [[lead(), guest()], [lead(), guest('Amet Guest', null)]], album);
    const summary = (await getAdminImportLookup(by, item.id)).summary;
    assert.deepEqual(summary.trackArtists![0].entries.map(value => value.identity), [album[0].key, album[1].key]);
    assert.deepEqual(summary.trackIdentities!.map(value => value.name), ['Amet Guest']);
    // The second track is deselected: Amet Guest needs no decision and is not created; the album guest's Artist credits the first.
    const writes = [{ scope: 'artist', entryKey: album[1].key, musicBrainzId: mbid(3), replaces: null }];
    const { frozen, done } = await publish(storage, item, { trackArtists: [{ slotId: slots[0], selected: true }, { slotId: slots[1], selected: false }], musicBrainzIds: writes });
    assert.deepEqual([frozen.schemaVersion, frozen.trackIdentities, frozen.trackArtists!.map(value => value.slotId)], [4, [], [slots[0]]]);
    const [lorem, albumGuest] = done.published!.artistIds;
    assert.deepEqual((await credits(done.published!.trackIds[0])).map(value => [value.subjectId, value.role]), [[lorem, 'primary'], [albumGuest, 'featured']]);
    assert.deepEqual((await credits(done.published!.trackIds[1])).map(value => [value.subjectId, value.role, value.joinPhrase]), [[lorem, 'primary', undefined]]);
    assert.equal(await db().collection('artists').countDocuments({ name: 'Amet Guest' }), 0);
    // Every listed track deselected: format 3 whose snapshot keeps the entries, committed with the Album's primaries.
    const next = await project(storage, [[lead(), guest('Consectetur Guest', null)]], [entry('Adipiscing Lead')], 'Second Collection');
    const all = await publish(storage, next.item, { trackArtists: [{ slotId: next.slots[0], selected: false }] });
    assert.deepEqual([all.frozen.schemaVersion, Boolean((all.frozen.snapshot as ImportDraftV2).tracks[0].artists), all.done.publication], [3, true, 'complete']);
    assert.deepEqual((await credits(all.done.published!.trackIds[0])).map(value => value.subjectId), all.done.published!.artistIds);
    assert.equal(await db().collection('artists').countDocuments({ name: 'Consectetur Guest' }), 0);
});

test('the approval refuses a body without the listed tracks, with another set, or with a stale digest after the entries changed, and an append ignores track entries', async () => {
    const storage = new Storage(), { item, slots } = await project(storage, [null, [lead(), guest('Ipsum Guest', null)]]), before = await stored(item.id);
    await assert.rejects(publishAdminImport(by, item.id, approvalBody(item)), code('ADMIN_IMPORT_RELOAD_REQUIRED'));
    for (const trackArtists of [[], [{ slotId: slots[0], selected: true }], [{ slotId: slots[1], selected: true }, { slotId: slots[0], selected: true }]])
        await assert.rejects(publishAdminImport(by, item.id, approvalBody(item, { trackArtists })), code('ADMIN_IMPORT_REVIEW_REQUIRED'), JSON.stringify(trackArtists));
    assert.deepEqual(await stored(item.id), before);
    // Another candidate's entries since the confirmation read make its digest stale.
    await imports().updateOne({ _id: new ObjectId(item.id) }, { $set: { [`draft.tracks.1.artists.1.name`]: 'Other Guest' } });
    await assert.rejects(publishAdminImport(by, item.id, approvalBody(item, { trackArtists: [{ slotId: slots[1], selected: true }] })), code('ADMIN_IMPORT_APPROVAL_STALE'));
    // An append (the Album reused) publishes every track with the target's primaries, whatever its draft's entries.
    const target = await publish(storage, (await project(storage, [null])).item);
    const appended = await project(storage, [[lead(), guest('Appended Guest', null)]]);
    // A title no member has, so the file is preselected as a new member of the target.
    await imports().updateOne({ _id: new ObjectId(appended.item.id) }, { $set: { 'draft.tracks.0.title': 'Appended Song' } });
    appended.item = (await getAdminImport(by, appended.item.id)).item;
    const album = (await adminImportDuplicateCandidates(by, appended.item.id)).items.find(value => value.kind === 'album' && value.id === target.done.published!.albumId)!;
    const decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: album.id, candidateRevision: album.revision }];
    const decided = (await decideAdminImportDuplicates(by, appended.item.id, { ...mutation(appended.item.revision), decisions })).item;
    const appendSummary = (await getAdminImportLookup(by, appended.item.id)).summary;
    assert.deepEqual(['trackArtists', 'trackIdentities'].filter(name => name in appendSummary), []);
    const { frozen, done } = await publish(storage, decided, { trackArtists: [{ slotId: appended.slots[0], selected: true }] });
    assert.deepEqual([frozen.schemaVersion, done.publication], [3, 'complete']);
    const added = done.published!.trackIds.find(id => !target.done.published!.trackIds.includes(id))!;
    assert.deepEqual((await credits(added)).map(value => value.subjectId), target.done.published!.artistIds);
    assert.equal(await db().collection('artists').countDocuments({ name: 'Appended Guest' }), 0);
});

test('two track entries decided to reuse one Artist (a rewritten document) are refused, writing nothing', async () => {
    const storage = new Storage(), existing = new ObjectId();
    await db().collection('artists').insertOne({ _id: existing, name: 'Ipsum Guest', albumIds: [], visibility: 'public', lifecycleStatus: 'ready' });
    const { item, slots } = await project(storage, [[lead(), guest('Ipsum Guest', null)], [lead(), guest('Dolor Guest', null)]]);
    const candidate = (await adminImportDuplicateCandidates(by, item.id)).items.find(value => value.id === existing.toHexString())!;
    const reuse = (name: string) => ({ scope: 'artist', slotId: null, entryKey: handle(`name:${name.toLowerCase()}`), boundName: name, boundMusicBrainzId: null, action: 'reuse', candidateId: candidate.id, candidateRevision: candidate.revision });
    await imports().updateOne({ _id: new ObjectId(item.id) }, { $set: { decisions: [reuse('Ipsum Guest'), reuse('Dolor Guest')] } });
    const shown = (await getAdminImport(by, item.id)).item, before = await stored(item.id);
    await assert.rejects(publishAdminImport(by, item.id, approvalBody(shown, { trackArtists: slots.map(slotId => ({ slotId, selected: true })) })), (error: unknown) => error instanceof AdminImportError && [400, 409].includes(error.status));
    assert.deepEqual(await stored(item.id), before);
});

test('the worker rechecks a format-4 approval: a new name candidate for a preselected track-only Artist, a changed reused one, and a rewritten approval mint nothing', async () => {
    const storage = new Storage(), { item, slots } = await project(storage, [[lead(), guest('Ipsum Guest', null)]]);
    await publishAdminImport(by, item.id, approvalBody(item, { trackArtists: [{ slotId: slots[0], selected: true }] }));
    await db().collection('artists').insertOne({ _id: new ObjectId(), name: 'ipsum guest', albumIds: [], visibility: 'public', lifecycleStatus: 'ready' });
    const before = await counts();
    await runAdminImportPublicationOnce(storage, item.id);
    const held = (await stored(item.id)).media!.publication!;
    assert.deepEqual([held.schemaVersion, held.state, held.issue, await counts()], [4, 'needsAttention', 'identityConflict', before]);
    // A reused track-only Artist that changes after approval is a catalog conflict.
    for (const name of ['artists', 'albums', 'audioTracks']) await db().collection(name).deleteMany({});
    const reused = new ObjectId();
    await db().collection('artists').insertOne({ _id: reused, name: 'Dolor Guest', musicBrainzId: mbid(7), albumIds: [], visibility: 'public', lifecycleStatus: 'ready' });
    const second = await project(storage, [[lead(), guest('Dolor Guest', mbid(7))]]);
    await publishAdminImport(by, second.item.id, approvalBody(second.item, { trackArtists: [{ slotId: second.slots[0], selected: true }] }));
    assert.equal((await stored(second.item.id)).media!.publication!.trackIdentities![0].artistId, reused.toHexString());
    await db().collection('artists').updateOne({ _id: reused }, { $set: { name: 'Corrected' } });
    await runAdminImportPublicationOnce(storage, second.item.id);
    assert.deepEqual([(await stored(second.item.id)).media!.publication!.issue, await db().collection('albums').countDocuments()], ['catalogConflict', 0]);
    // A rewritten approval: an orphan identity, an unknown Artist in a list, one Artist twice in a list, or a newer format.
    const rewrites: Record<string, unknown>[] = [
        { 'media.publication.trackIdentities.1': { entryKey: randomUUID(), name: 'Orphan', musicBrainzId: null, artistId: new ObjectId().toHexString(), newArtist: true, candidateRevision: null } },
        { 'media.publication.trackArtists.0.entries.1.artistId': new ObjectId().toHexString() },
        { 'media.publication.trackArtists.0.entries.1.artistId': 'FIRST' }, { 'media.publication.schemaVersion': 5 }];
    for (const [index, rewrite] of rewrites.entries()) {
        for (const name of ['artists', 'albums', 'audioTracks']) await db().collection(name).deleteMany({});
        const next = await project(storage, [[lead(), guest(`Guest ${index}`, null)]], [entry(`Lead ${index}`)]);
        await publishAdminImport(by, next.item.id, approvalBody(next.item, { trackArtists: [{ slotId: next.slots[0], selected: true }] }));
        const frozen = (await stored(next.item.id)).media!.publication!;
        const value = Object.fromEntries(Object.entries(rewrite).map(([path, target]) => [path, target === 'FIRST' ? frozen.trackArtists![0].entries[0].artistId : target]));
        await imports().updateOne({ _id: new ObjectId(next.item.id) }, { $set: value });
        await runAdminImportPublicationOnce(storage, next.item.id);
        const result = (await stored(next.item.id)).media!.publication!;
        assert.deepEqual([result.state, result.issue, await db().collection('albums').countDocuments(), await db().collection('artists').countDocuments()],
            ['needsAttention', index === 3 ? 'unsupportedVersion' : 'catalogConflict', 0, 0], JSON.stringify(Object.keys(rewrite)));
    }
});


test('a format-4 approval replays its original intent and resumes an interrupted copy with the same track-only identities once', async () => {
    const controller = new AbortController();
    class InterruptedStorage extends Storage {
        stopAfterCopy = true;
        override async copy(source: ImportObjectTarget & ImportObjectIdentity, target: ImportObjectTarget) {
            const result = await super.copy(source, target);
            if (this.stopAfterCopy) controller.abort();
            return result;
        }
    }
    const storage = new InterruptedStorage(), { item, slots } = await project(storage, [[lead(), guest('Retry Guest', null)], null]);
    const body = approvalBody(item, { trackArtists: [{ slotId: slots[0], selected: true }] });
    const admitted = await publishAdminImport(by, item.id, body), original = (await stored(item.id)).media!.publication!;
    const replayed = await publishAdminImport(by, item.id, body);
    assert.deepEqual(replayed.receipt, admitted.receipt);
    assert.deepEqual((await stored(item.id)).media!.publication, original);
    await runAdminImportPublicationOnce(storage, item.id, controller.signal);
    // An interruption after the first copy retains its exact object and the original frozen identities.
    assert.equal(storage.copies, 1);
    const held = (await stored(item.id)).media!.publication!;
    assert.deepEqual([held.state, held.issue, await counts()], ['needsAttention', 'storageUnknown', { artists: 0, albums: 0, audioTracks: 0 }]);
    assert.deepEqual(held.trackIdentities, original.trackIdentities);
    assert.equal(held.tracks[0].state, 'ready');
    storage.stopAfterCopy = false;
    const resumed = await resumeAdminImportPublication(by, item.id, body.operationId, storage);
    assert.equal(resumed.item.publication, 'complete');
    assert.deepEqual(resumed.item.published!.artistIds, [...original.artists!.map(value => value.artistId), ...original.trackIdentities!.map(value => value.artistId)]);
    assert.deepEqual(await counts(), { artists: 2, albums: 1, audioTracks: 2 });
    assert.equal(storage.copies, 2);
    const again = await resumeAdminImportPublication(by, item.id, body.operationId, storage);
    assert.deepEqual(again.item.published, resumed.item.published);
    assert.equal(storage.copies, 2);
    assert.deepEqual(await counts(), { artists: 2, albums: 1, audioTracks: 2 });
});

for (const exclusion of ['deselect', 'skip'] as const) {
    test(`${exclusion} excludes an unused stale track-only Artist decision before publication validates reused revisions`, async () => {
        const storage = new Storage(), existing = new ObjectId(), guestName = 'Unused Guest', guestKey = handle('name:unused guest');
        await db().collection('artists').insertOne({ _id: existing, name: guestName, albumIds: [], visibility: 'public', lifecycleStatus: 'ready' });
        const { item, slots } = await project(storage, [[lead(), guest(guestName, null)], null]);
        const candidate = (await adminImportDuplicateCandidates(by, item.id)).items.find(value => value.id === existing.toHexString())!;
        const reuse = { scope: 'artist', slotId: null, entryKey: guestKey, boundName: guestName, action: 'reuse', candidateId: candidate.id, candidateRevision: candidate.revision };
        const decided = (await decideAdminImportDuplicates(by, item.id, { ...mutation(item.revision), decisions: [...item.decisions, reuse] })).item;
        await db().collection('artists').updateOne({ _id: existing }, { $set: { name: 'Corrected Unused Guest' } });
        const before = await stored(item.id);
        // Keeping the track's own entries still requires a fresh review of the reused Artist.
        await assert.rejects(publishAdminImport(by, item.id, approvalBody(decided, { trackArtists: [{ slotId: slots[0], selected: true }] })), code('ADMIN_IMPORT_DUPLICATE_STALE'));
        assert.deepEqual(await stored(item.id), before);

        // The confirmation may still carry the old explicit reuse while the administrator unticks or skips its only track.
        const decisions = exclusion === 'skip' ? [...decided.decisions, { scope: 'track', slotId: slots[0], entryKey: null, boundName: null,
            action: 'skip', candidateId: null, candidateRevision: null }] : decided.decisions;
        const { frozen, done } = await publish(storage, decided, { decisions, trackArtists: [{ slotId: slots[0], selected: exclusion === 'skip' }] });
        assert.equal(done.publication, 'complete');
        assert.deepEqual([frozen.schemaVersion, frozen.trackIdentities, frozen.trackArtists], [3, undefined, undefined]);
        assert.equal(frozen.decisions.some(decision => decision.scope === 'artist' && (decision as { entryKey?: string }).entryKey === guestKey), false);
        const [primary] = done.published!.artistIds;
        assert.equal(done.published!.artistIds.length, 1);
        assert.equal(done.published!.trackIds.length, exclusion === 'skip' ? 1 : 2);
        for (const trackId of done.published!.trackIds) assert.deepEqual((await credits(trackId)).map(credit => credit.subjectId), [primary]);
        assert.deepEqual([(await row('artists', existing.toHexString()))!.name, (await row('artists', existing.toHexString()))!.albumIds], ['Corrected Unused Guest', []]);
        assert.equal(await db().collection('artists').countDocuments({ name: guestName }), 0);
        assert.deepEqual(await counts(), { artists: 2, albums: 1, audioTracks: exclusion === 'skip' ? 1 : 2 });
    });
}
